def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay keys[i]=values[i] on the defaults mode=fast and level=3. Return mode, level, then the other keys in the order given."""
    pre keys.len() == values.len()
    post out.len() >= 2
    ex settings([], []) == ["fast", "3"]
    ex settings(["mode"], ["slow"]) == ["slow", "3"]
    ex settings(["level", "color"], ["5", "red"]) == ["fast", "5", "red"]
    mode = "fast"
    level = "3"
    others: dict[str, str] = {}
    order: list[str] = []
    for i in range(keys.len()):
        k = keys[i]
        v = values[i]
        if k == "mode":
            mode = v.copy()
        elif k == "level":
            level = v.copy()
        else:
            if k not in others:
                order.append(k.copy())
            others[k] = v.copy()
    out: list[str] = [mode, level]
    for k in order:
        out.append((others.get(k) else "").copy())
    return out
